// WebGL2 surface management — the GL twin of gpu.ts. Owns context acquisition,
// canvas fitting (premultiplied alpha, dpr-capped backing store) and CONTEXT-
// LOSS recovery: on `webglcontextlost` every GL-side resource is recreated from
// CPU-side state via the registered rebuild callbacks, mirroring the WebGPU
// device-loss flow (the twins share the rebuild discipline).
//
// Module load is DOM-free (testable in Node): all DOM/GL access happens inside
// init().

export interface GlOptions {
  /** Cap on devicePixelRatio for the backing store (default 1 — see gpu.ts). */
  dprCap?: number;
  /** Called with any GL/page error message (context loss, shader failures). */
  onError?: (msg: string) => void;
}

/** The live WebGL2 handles for one canvas, with context-loss recovery built in. */
export class GlContext {
  private rebuildFns = new Set<(gl: WebGL2RenderingContext) => void>();
  private lostForever = false;
  private destroyed = false;
  private dirty = true;
  private ro: ResizeObserver | null = null;
  private dprMql: MediaQueryList | null = null;
  private onDprChange: (() => void) | null = null;

  private constructor(
    public gl: WebGL2RenderingContext,
    readonly canvas: HTMLCanvasElement,
    private opts: GlOptions,
  ) {}

  /**
   * Acquire a WebGL2 context configured for premultiplied-alpha presentation
   * (matching the WebGPU surface) with an antialiased, depth'd default
   * framebuffer. Returns null where WebGL2 is absent.
   */
  static init(canvas: HTMLCanvasElement, opts: GlOptions = {}): GlContext | null {
    if (typeof canvas.getContext !== 'function') return null;
    const gl = canvas.getContext('webgl2', {
      alpha: true,
      premultipliedAlpha: true,
      antialias: true,          // the MSAA stand-in for the default framebuffer
      depth: true,
      stencil: false,
      powerPreference: 'high-performance',
      // No preserveDrawingBuffer: screenshot() drains at end-of-frame inside the
      // same rAF tick, before compositing clears — matching WebGPU semantics.
    });
    if (!gl) return null;
    const self = new GlContext(gl, canvas, opts);
    canvas.addEventListener('webglcontextlost', (e) => {
      e.preventDefault(); // signal we intend to restore
      self.opts.onError?.('WebGL context lost — waiting for restore…');
    });
    canvas.addEventListener('webglcontextrestored', () => {
      if (self.destroyed) return;
      for (const fn of self.rebuildFns) fn(self.gl);
      self.opts.onError?.('WebGL context restored.');
    });
    self.fit();
    self.watchSize();
    return self;
  }

  /** Watch the canvas for size / dpr changes — same event-driven scheme as Gpu. */
  private watchSize(): void {
    if (typeof window === 'undefined') return;
    if (typeof ResizeObserver !== 'undefined') {
      this.ro = new ResizeObserver(() => { this.dirty = true; });
      this.ro.observe(this.canvas);
    }
    const armDpr = (): void => {
      const dpr = window.devicePixelRatio || 1;
      this.dprMql = window.matchMedia(`(resolution: ${dpr}dppx)`);
      this.onDprChange = (): void => { this.dirty = true; armDpr(); };
      this.dprMql.addEventListener('change', this.onDprChange, { once: true });
    };
    armDpr();
  }

  /** Force the next `fit()` to re-measure (e.g. after a manual layout change). */
  markDirty(): void {
    this.dirty = true;
  }

  /** Register a rebuild callback fired after a lost context is restored. */
  onRebuild(fn: (gl: WebGL2RenderingContext) => void): () => void {
    this.rebuildFns.add(fn);
    return () => this.rebuildFns.delete(fn);
  }

  /** Size the backing store to CSS size × dpr (capped) — the Gpu.fit twin. */
  fit(): boolean {
    if (!this.dirty) return false;
    this.dirty = false;
    const dpr = Math.min(this.opts.dprCap ?? 1, (typeof window !== 'undefined' && window.devicePixelRatio) || 1);
    const w = Math.max(1, Math.floor((this.canvas.clientWidth || window.innerWidth) * dpr));
    const h = Math.max(1, Math.floor((this.canvas.clientHeight || window.innerHeight) * dpr));
    if (w === this.canvas.width && h === this.canvas.height) return false;
    this.canvas.width = w;
    this.canvas.height = h;
    return true;
  }

  /** True once the context is gone for good (only after destroy()). */
  get dead(): boolean {
    return this.lostForever || (this.gl.isContextLost() && this.destroyed);
  }

  /** Tear down: stop watching size and drop rebuild hooks. Idempotent. */
  destroy(): void {
    if (this.destroyed) return;
    this.destroyed = true;
    this.ro?.disconnect();
    this.ro = null;
    if (this.dprMql && this.onDprChange) this.dprMql.removeEventListener('change', this.onDprChange);
    this.dprMql = null;
    this.onDprChange = null;
    this.rebuildFns.clear();
    this.gl.getExtension('WEBGL_lose_context')?.loseContext();
    this.lostForever = true;
  }
}
