// The WebGL2 twin of lights2d.ts's Lights2d — additive 2D lights + multiply
// ambient. The heavy lifting (visibility polygons via the real Visibility2d,
// soft-shadow disc sampling, flicker, culling, the under/over split) is pure
// CPU in the WebGPU original and is duplicated verbatim here; the same
// 16-float triangle instances feed an instanced additive program, and the
// ambient pass is a fullscreen multiply (gl.DST_COLOR, gl.ZERO).
//
// The under/over phases share one upload: 'under' builds + uploads the whole
// frame and draws [0, underTris); 'over' draws the ambient multiply then
// [underTris, count). WebGL2 has no firstInstance, so the 'over' range binds
// its attribute pointers at a byte offset (first × 64) instead.

import { Visibility2d } from '../visibility2d.js';
import type { Light2d, PointLight2dOptions, SpotLight2dOptions } from '../lights2d.js';
import { GLSL_HEADER, GLSL_FRAG_HEADER, compileProgram, InstanceBuffer } from './shaders.js';

const FLOATS = 16; // per triangle instance: tri(4) triC(4) params(4) color(4)
const STRIDE_BYTES = FLOATS * 4;

// Penumbra sampling: a soft-shadow light is sampled as a small disc of this
// many points (sunflower/golden-angle spread over the unit disc). The union of
// their hard visibility polygons, each at 1/N intensity, is a real soft shadow.
const SOFT_DISK: Array<[number, number]> = (() => {
  const N = 12, out: Array<[number, number]> = [];
  const golden = Math.PI * (3 - Math.sqrt(5));
  for (let k = 0; k < N; k++) { const r = Math.sqrt((k + 0.5) / N); const a = k * golden; out.push([Math.cos(a) * r, Math.sin(a) * r]); }
  return out;
})();
const HARD_SAMPLE: Array<[number, number]> = [[0, 0]];

/** Light-triangle vertex shader — the GLSL port of lights2d.ts's `vs`. */
export const buildLightVertGLSL = (): string => GLSL_HEADER + /* glsl */ `
layout(location=0) in vec4 iTri;     // ax, ay, bx, by
layout(location=1) in vec4 iTriC;    // cx, cy, lightX, lightY
layout(location=2) in vec4 iParams;  // radius, intensity, coneCos, coneDir
layout(location=3) in vec4 iColor;   // r, g, b, falloffPow
uniform vec4 uView;                  // world rect mapped to the canvas: x, y, w, h
out vec2 vWorld;
out vec2 vLight;
out vec4 vParams;
out vec4 vColor;
void main() {
  vec2 p = iTriC.xy;                      // vertex 2 = the light centre
  if (gl_VertexID == 0) { p = iTri.xy; }  // vertex 0 = A
  else if (gl_VertexID == 1) { p = iTri.zw; } // vertex 1 = B
  vec2 ndc = (p - uView.xy) / uView.zw * 2.0 - 1.0;
  gl_Position = vec4(ndc.x, -ndc.y, 0.0, 1.0);
  vWorld = p;
  vLight = iTriC.zw;
  vParams = iParams;
  vColor = iColor;
}
`;

/** Light-triangle fragment shader — per-pixel falloff + spot cone. */
export const buildLightFragGLSL = (): string => GLSL_FRAG_HEADER + /* glsl */ `
in vec2 vWorld;
in vec2 vLight;
in vec4 vParams;
in vec4 vColor;
out vec4 outColor;
void main() {
  float dist = distance(vWorld, vLight);
  float radius = vParams.x;
  float atten = clamp(1.0 - dist / radius, 0.0, 1.0);
  atten = pow(atten, max(vColor.w, 0.25));
  float coneCos = vParams.z;
  if (coneCos > -1.5) {                   // spot: fade outside the cone
    float da = atan(vWorld.y - vLight.y, vWorld.x - vLight.x) - vParams.w;
    float cd = cos(da);
    atten = atten * smoothstep(coneCos, mix(coneCos, 1.0, 0.15), cd);
  }
  float b = atten * vParams.y;
  outColor = vec4(vColor.rgb * b, b);     // premultiplied — additive one/one
}
`;

/** Ambient fullscreen-triangle vertex shader. */
export const buildAmbientVertGLSL = (): string => GLSL_HEADER + /* glsl */ `
void main() {
  vec2 p = vec2(-1.0, -1.0);
  if (gl_VertexID == 1) { p = vec2(3.0, -1.0); }
  else if (gl_VertexID == 2) { p = vec2(-1.0, 3.0); }
  gl_Position = vec4(p, 0.0, 1.0);
}
`;

/** Ambient fragment — the colour the scene multiplies down to. */
export const buildAmbientFragGLSL = (): string => GLSL_FRAG_HEADER + /* glsl */ `
uniform vec4 uColor;
out vec4 outColor;
void main() { outColor = uColor; }
`;

/**
 * The 2D light layer — the GL twin of Lights2d. Add occluders + lights,
 * mutate them each frame; draw('under'/'over') renders each phase into the
 * current framebuffer.
 */
export class GlLights2d {
  /** Scenery that casts shadows — add rects / segments / polys to it. */
  readonly occluders = new Visibility2d();
  /** The active lights (mutate freely; `point()`/`spot()` append here). */
  readonly lights: Light2d[] = [];
  /** Ambient (base) light colour — the scene is multiplied down to this
   *  before the over-lights add (white = no darkening). */
  ambient: [number, number, number] = [1, 1, 1];
  /** Lights drawn last frame after culling — for HUD/debug. */
  visible = 0;
  /** Of those, how many cast shadows (the expensive ones) — for HUD/debug. */
  visibleShadow = 0;

  private data: Float32Array;
  private count = 0;
  private capacity = 4096;
  private time = 0;
  private uniformData = new Float32Array(4);
  private ambientData = new Float32Array(4);
  private vx = 0; private vy = 0; private vw = 0; private vh = 0;
  private underTris = 0;   // triangle count of the 'under' layer (draw split point)

  private gl!: WebGL2RenderingContext;
  private program: WebGLProgram | null = null;
  private ambientProgram: WebGLProgram | null = null;
  private uViewLoc: WebGLUniformLocation | null = null;
  private uColorLoc: WebGLUniformLocation | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private instances!: InstanceBuffer;
  private vbo: WebGLBuffer | null = null;

  constructor(gl: WebGL2RenderingContext) {
    this.data = new Float32Array(this.capacity * FLOATS);
    this.rebuild(gl);
  }

  /** (Re)create every GL-side object — the context-loss recovery path. */
  rebuild(gl: WebGL2RenderingContext): void {
    this.gl = gl;
    this.program = compileProgram(gl, buildLightVertGLSL(), buildLightFragGLSL(), 'GlLights2d');
    this.ambientProgram = compileProgram(gl, buildAmbientVertGLSL(), buildAmbientFragGLSL(), 'GlLights2d ambient');
    this.uViewLoc = this.program ? gl.getUniformLocation(this.program, 'uView') : null;
    this.uColorLoc = this.ambientProgram ? gl.getUniformLocation(this.ambientProgram, 'uColor') : null;
    this.instances = new InstanceBuffer(gl);
    this.vao = null;
    this.vbo = null;
  }

  // ── Lights ─────────────────────────────────────────────────────────────────

  // Defaults MUST track lights2d.ts's point()/spot() field-for-field — the
  // same game must light identically on either backend.
  private makeLight(type: 'point' | 'spot', x: number, y: number, opts: SpotLight2dOptions, radius: number): Light2d {
    const light: Light2d = {
      type, x, y,
      radius: opts.radius ?? radius,
      intensity: opts.intensity ?? 1,
      color: opts.color ?? [1, 1, 1],
      falloff: opts.falloff ?? 2,
      dir: opts.dir ?? 0,
      cone: opts.cone ?? (type === 'spot' ? 0.9 : 0),
      flicker: opts.flicker ?? 0,
      flickerSpeed: opts.flickerSpeed ?? 1,
      phase: opts.phase ?? 0,
      layer: opts.layer ?? 'over',
      shadows: opts.shadows ?? false,
      softness: opts.softness ?? 6,
      on: true,
    };
    this.lights.push(light);
    return light;
  }

  /** Add a point light; returns its handle (mutate to move / recolour it). */
  point(x: number, y: number, opts: PointLight2dOptions = {}): Light2d {
    return this.makeLight('point', x, y, opts, 240);
  }

  /** Add a spot light (a cone). `dir` faces in radians, `cone` is the full angle. */
  spot(x: number, y: number, opts: SpotLight2dOptions = {}): Light2d {
    return this.makeLight('spot', x, y, opts, 360);
  }

  /** Remove a light. */
  remove(light: Light2d): void {
    const i = this.lights.indexOf(light);
    if (i >= 0) this.lights.splice(i, 1);
  }

  /** Remove all lights. */
  clear(): void { this.lights.length = 0; }

  // ── Frame ──────────────────────────────────────────────────────────────────

  /** Start a frame: map the world rect onto the canvas (same as the batches). */
  begin(viewX: number, viewY: number, viewW: number, viewH: number, time: number): void {
    this.uniformData[0] = viewX; this.uniformData[1] = viewY;
    this.uniformData[2] = viewW; this.uniformData[3] = viewH;
    this.vx = viewX; this.vy = viewY; this.vw = viewW; this.vh = viewH;
    this.time = time;
    // Shadowed lights' rays terminate at the visible window.
    this.occluders.setBounds(viewX, viewY, viewW, viewH);
    this.count = 0;
  }

  private flicker(l: Light2d): number {
    if (l.flicker <= 0) return 1;
    const t = this.time * l.flickerSpeed;
    // Layered sines → an irregular, candle-like wobble in [0,1].
    const n = 0.5 + 0.5 * (Math.sin(t * 11.3 + l.phase) * 0.6 + Math.sin(t * 23.7 + l.phase * 1.7) * 0.4);
    return 1 - l.flicker * (1 - n);
  }

  // Push one triangle (corners A, B, C) carrying the light params. C is a real
  // corner; the light centre (lx, ly) is stored separately for the fragment
  // falloff — so the same instance format serves the shadow FAN (C = the light
  // centre / apex) and the plain QUAD (C = a bbox corner).
  private pushTri(ax: number, ay: number, bx: number, by: number, cx: number, cy: number, lx: number, ly: number, radius: number, intensity: number, coneCos: number, coneDir: number, col: [number, number, number], pow: number): void {
    if (this.count >= this.capacity) this.grow();
    const o = this.count * FLOATS, d = this.data;
    d[o] = ax; d[o + 1] = ay; d[o + 2] = bx; d[o + 3] = by;
    d[o + 4] = cx; d[o + 5] = cy; d[o + 6] = lx; d[o + 7] = ly;
    d[o + 8] = radius; d[o + 9] = intensity; d[o + 10] = coneCos; d[o + 11] = coneDir;
    d[o + 12] = col[0]; d[o + 13] = col[1]; d[o + 14] = col[2]; d[o + 15] = pow;
    this.count++;
  }

  private grow(): void {
    this.capacity *= 2;
    const next = new Float32Array(this.capacity * FLOATS);
    next.set(this.data);
    this.data = next;
  }

  /** @internal Cull + tessellate one light — a plain radial QUAD (2 triangles)
   *  by default, or the shadowed visibility FAN when it opts in. */
  private emitLight(l: Light2d): void {
    if (!l.on || l.radius <= 0) return;
    // Cull: the light's reach circle must touch the visible window.
    if (l.x + l.radius < this.vx || l.x - l.radius > this.vx + this.vw ||
        l.y + l.radius < this.vy || l.y - l.radius > this.vy + this.vh) return;
    const intensity = l.intensity * this.flicker(l);
    if (intensity <= 0.001) return;
    const coneCos = l.type === 'spot' ? Math.cos(l.cone * 0.5) : -2;
    this.visible++;
    if (l.shadows) {
      this.visibleShadow++;
      // Shadowed: fan the visibility polygon (apex = the light). Soft shadows
      // sample the light as a disc — the union of the jittered polygons at
      // 1/N intensity is the penumbra.
      const samples = l.softness > 0 ? SOFT_DISK : HARD_SAMPLE;
      const sub = intensity / samples.length;
      for (const [ox, oy] of samples) {
        const lx = l.x + ox * l.softness, ly = l.y + oy * l.softness;
        const poly = this.occluders.visibility(lx, ly, l.radius);
        if (poly.length < 2) continue;
        for (let i = 0; i < poly.length; i++) {
          const a = poly[i], b = poly[(i + 1) % poly.length];
          this.pushTri(a.x, a.y, b.x, b.y, lx, ly, lx, ly, l.radius, sub, coneCos, l.dir, l.color, l.falloff);
        }
      }
    } else {
      // Plain glow: a quad covering the reach circle (falloff does the shape).
      const r = l.radius;
      const x0 = l.x - r, y0 = l.y - r, x1 = l.x + r, y1 = l.y + r;
      this.pushTri(x0, y0, x1, y0, x0, y1, l.x, l.y, r, intensity, coneCos, l.dir, l.color, l.falloff);
      this.pushTri(x1, y0, x1, y1, x0, y1, l.x, l.y, r, intensity, coneCos, l.dir, l.color, l.falloff);
    }
  }

  /** @internal Emit UNDER-layer lights first (`[0, underTris)`) then OVER-layer
   *  (`[underTris, count)`), so the two draw phases can pick their sub-range. */
  private buildAll(): void {
    this.count = 0; this.visible = 0; this.visibleShadow = 0;
    for (const l of this.lights) if (l.layer === 'under') this.emitLight(l);
    this.underTris = this.count;
    for (const l of this.lights) if (l.layer !== 'under') this.emitLight(l);
  }

  /** Bind the 4 instance vec4s at `byteOffset` — the firstInstance emulation
   *  for the 'over' sub-range. Needs the instance VBO bound. */
  private bindAttribs(byteOffset: number): void {
    const gl = this.gl;
    for (let i = 0; i < 4; i++) {
      gl.enableVertexAttribArray(i);
      gl.vertexAttribPointer(i, 4, gl.FLOAT, false, STRIDE_BYTES, byteOffset + i * 16);
      gl.vertexAttribDivisor(i, 1);
    }
  }

  /**
   * Draw one compositing PHASE into the current framebuffer. `'under'`
   * (called before the sprite batches) builds + uploads the whole frame and
   * draws the floor lights; `'over'` (called after the scene) multiplies the
   * scene to the ambient colour then draws the lights that cover the sprites.
   */
  draw(_pass?: unknown, phase: 'under' | 'over' = 'under'): void {
    const gl = this.gl;
    if (!this.program) return;
    if (phase === 'under') {
      this.buildAll();
      if (this.count > 0) this.vbo = this.instances.upload(this.data, this.count * FLOATS);
    } else {
      this.drawAmbient();   // darken the scene to the ambient base, then the lights add
    }
    const first = phase === 'under' ? 0 : this.underTris;
    const num = phase === 'under' ? this.underTris : this.count - this.underTris;
    if (num <= 0 || !this.vbo) return;
    gl.useProgram(this.program);
    gl.uniform4fv(this.uViewLoc, this.uniformData);
    if (!this.vao) this.vao = gl.createVertexArray();
    gl.bindVertexArray(this.vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.vbo);
    this.bindAttribs(first * STRIDE_BYTES);
    // Pipeline state: additive (colours MIX), depth ignored entirely.
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE);
    gl.disable(gl.DEPTH_TEST);
    gl.depthMask(false);
    gl.drawArraysInstanced(gl.TRIANGLES, 0, 3, num);
    gl.bindVertexArray(null);
  }

  /** @internal Multiply the scene down to the ambient colour (skipped when the
   *  ambient is white — no darkening). */
  private drawAmbient(): void {
    const gl = this.gl;
    if (!this.ambientProgram) return;
    const [r, g, b] = this.ambient;
    if (r >= 0.999 && g >= 0.999 && b >= 0.999) return;
    this.ambientData[0] = r; this.ambientData[1] = g; this.ambientData[2] = b; this.ambientData[3] = 1;
    gl.useProgram(this.ambientProgram);
    gl.uniform4fv(this.uColorLoc, this.ambientData);
    if (!this.vao) this.vao = gl.createVertexArray();
    gl.bindVertexArray(this.vao);
    gl.enable(gl.BLEND);
    // result = ambient × scene; keep dst alpha.
    gl.blendFuncSeparate(gl.DST_COLOR, gl.ZERO, gl.ZERO, gl.ONE);
    gl.disable(gl.DEPTH_TEST);
    gl.depthMask(false);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.bindVertexArray(null);
  }
}
