// The WebGL2 twin of tribatch.ts — flat filled triangles for `d.fill`. Same
// 12-float instance packing; each instance draws 3 verts whose corner is
// picked by gl_VertexID, exactly mirroring the WGSL.

import { GLSL_HEADER, GLSL_FRAG_HEADER, compileProgram, instanceVec4Attribs, InstanceBuffer } from './shaders.js';
import { SRC_TRI, type DrawOrder } from '../batch.js';

const FLOATS = 12; // per triangle: tri(4: ax,ay,bx,by) c(4: cx,cy,_,_) color(4)

export const buildTriVertGLSL = (): string => GLSL_HEADER + /* glsl */ `
layout(location=0) in vec4 iTri;   // ax, ay, bx, by
layout(location=1) in vec4 iC;     // cx, cy, _, _
layout(location=2) in vec4 iColor;
uniform vec4 uView;
out vec4 vColor;
void main() {
  vec2 p = iC.xy;
  if (gl_VertexID == 0) { p = iTri.xy; } else if (gl_VertexID == 1) { p = iTri.zw; }
  vec2 ndc = (p - uView.xy) / uView.zw * 2.0 - 1.0;
  gl_Position = vec4(ndc.x, -ndc.y, 0.0, 1.0);
  vColor = iColor;
}
`;

export const buildTriFragGLSL = (): string => GLSL_FRAG_HEADER + /* glsl */ `
in vec4 vColor;
out vec4 outColor;
void main() {
  outColor = vec4(vColor.rgb * vColor.a, vColor.a);   // premultiplied
}
`;

/** An instanced flat-triangle batch (alpha blend, no depth). */
export class GlTriBatch {
  /** The surface's submission-order log — see batch.ts's DrawOrder. */
  private order: DrawOrder | null = null;
  private layer = 0;

  /** @internal Take part in a surface's submission order. */
  joinOrder(order: DrawOrder): void { this.order = order; }
  /** @see QuadBatch.setLayer */
  setLayer(n: number): void { this.layer = n; }
  private data: Float32Array;
  private count = 0;
  private capacity = 2048;
  private uniformData = new Float32Array(4);

  private gl!: WebGL2RenderingContext;
  private program: WebGLProgram | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private instances!: InstanceBuffer;
  private uViewLoc: WebGLUniformLocation | null = null;

  constructor(gl: WebGL2RenderingContext) {
    this.data = new Float32Array(this.capacity * FLOATS);
    this.rebuild(gl);
  }

  rebuild(gl: WebGL2RenderingContext): void {
    this.gl = gl;
    this.program = compileProgram(gl, buildTriVertGLSL(), buildTriFragGLSL(), 'GlTriBatch');
    this.uViewLoc = this.program ? gl.getUniformLocation(this.program, 'uView') : null;
    this.instances = new InstanceBuffer(gl);
    this.vao = null;
  }

  begin(viewX: number, viewY: number, viewW: number, viewH: number): void {
    this.uniformData[0] = viewX; this.uniformData[1] = viewY;
    this.uniformData[2] = viewW; this.uniformData[3] = viewH;
    this.count = 0;
    this.layer = 0;
  }

  push(ax: number, ay: number, bx: number, by: number, cx: number, cy: number, r: number, g: number, b: number, a: number): void {
    this.order?.put(SRC_TRI, this.count, this.layer);
    if (this.count >= this.capacity) this.grow();
    const o = this.count * FLOATS, d = this.data;
    d[o] = ax; d[o + 1] = ay; d[o + 2] = bx; d[o + 3] = by;
    d[o + 4] = cx; d[o + 5] = cy; d[o + 6] = 0; d[o + 7] = 0;
    d[o + 8] = r; d[o + 9] = g; d[o + 10] = b; d[o + 11] = a;
    this.count++;
  }

  private grow(): void {
    this.capacity *= 2;
    const next = new Float32Array(this.capacity * FLOATS);
    next.set(this.data);
    this.data = next;
  }

  /** Program, VAO, upload and pipeline state — shared by both draw paths. */
  private bindForDraw(): void {
    const gl = this.gl;
    gl.useProgram(this.program!);
    gl.uniform4fv(this.uViewLoc, this.uniformData);
    if (!this.vao) this.vao = gl.createVertexArray();
    gl.bindVertexArray(this.vao);
    this.instances.upload(this.data, this.count * FLOATS);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    gl.disable(gl.DEPTH_TEST);   // WGSL twin: depth compare 'always', no write
    gl.depthMask(false);
  }

  /** @internal @see TriBatch.drawRange */
  drawRange(_pass: unknown, first: number, n: number): void {
    if (n <= 0 || this.count === 0 || !this.program) return;
    const gl = this.gl;
    this.bindForDraw();
    instanceVec4Attribs(gl, 0, 3, first * FLOATS * 4);
    gl.drawArraysInstanced(gl.TRIANGLES, 0, 3, n);
    gl.bindVertexArray(null);
  }

  flush(_pass?: unknown): void {
    const gl = this.gl;
    if (this.count === 0 || !this.program) return;
    this.bindForDraw();
    instanceVec4Attribs(gl, 0, 3);
    gl.drawArraysInstanced(gl.TRIANGLES, 0, 3, this.count);
    gl.bindVertexArray(null);
  }
}
