// The WebGL2 twin of glowpass.ts's GlowPass — TRUE per-object glow: every
// glowing sprite stamps its TINTED SILHOUETTE (additive, so overlaps sum)
// into a HALF-RESOLUTION FBO; the target gets a separable 13-tap gaussian
// blur (H→V, two iterations, spread scaled by the largest requested glow
// size); composite() adds the result over the scene. The vector layer's soft
// line cores stamp into the same target via the `extra` callback (it MAX-
// blends its own draws; we restore FUNC_ADD after).
//
// Fullscreen passes here use the IDENTITY corner mapping (pos = uv*2-1, uv
// straight through) instead of the WGSL's y-flipped one: GL framebuffers are
// bottom-up, so an identity copy in blur keeps orientation, and the composite
// then lands the world the right way up on the (equally bottom-up) scene
// target — the two flips cancel by never happening.
//
// Cost when nothing glows: zero (no passes run).

import type { Frame } from '../atlas.js';
import { GLSL_HEADER, GLSL_FRAG_HEADER, compileProgram, instanceVec4Attribs, InstanceBuffer } from './shaders.js';

const FLOATS = 16; // posSize | rot+flip+pad2 | color | uvRect

/** Stamp vertex shader — the GLSL port of STAMP_WGSL's `vs`. */
export const buildGlowStampVertGLSL = (): string => GLSL_HEADER + /* glsl */ `
layout(location=0) in vec4 iPosSize;
layout(location=1) in vec4 iMisc;   // rot, flipX, _, _
layout(location=2) in vec4 iColor;
layout(location=3) in vec4 iUv;
uniform vec4 uView;
out vec2 vUv;
out vec4 vColor;
void main() {
  vec2 c01 = vec2(float(gl_VertexID & 1), float(gl_VertexID >> 1));
  vec2 centre = iPosSize.xy + iPosSize.zw * 0.5;
  vec2 off = (c01 - 0.5) * iPosSize.zw;
  float sn = sin(iMisc.x);
  float cn = cos(iMisc.x);
  vec2 world = centre + vec2(off.x * cn - off.y * sn, off.x * sn + off.y * cn);
  vec2 ndc = (world - uView.xy) / uView.zw * 2.0 - 1.0;
  gl_Position = vec4(ndc.x, -ndc.y, 0.0, 1.0);
  float ux = c01.x;
  if (iMisc.y > 0.5) { ux = 1.0 - ux; }
  vUv = vec2(mix(iUv.x, iUv.z, ux), mix(iUv.y, iUv.w, c01.y));
  vColor = iColor;
}
`;

/** Stamp fragment shader — tinted silhouette, additive-summed. */
export const buildGlowStampFragGLSL = (): string => GLSL_FRAG_HEADER + /* glsl */ `
in vec2 vUv;
in vec4 vColor;
uniform sampler2D uTex;
out vec4 outColor;
void main() {
  float a = texture(uTex, vUv).a * vColor.a;
  outColor = vec4(vColor.rgb * a, a);   // tinted silhouette, additive-summed
}
`;

/** Shared fullscreen-triangle vertex shader (identity mapping — see header). */
export const buildFullscreenVertGLSL = (): string => GLSL_HEADER + /* glsl */ `
out vec2 vUv;
void main() {
  float x = float((gl_VertexID << 1) & 2);
  float y = float(gl_VertexID & 2);
  gl_Position = vec4(x * 2.0 - 1.0, y * 2.0 - 1.0, 0.0, 1.0);
  vUv = vec2(x, y);
}
`;

/** Separable 13-tap gaussian blur fragment — the GLSL port of BLUR_WGSL. */
export const buildGlowBlurFragGLSL = (): string => GLSL_FRAG_HEADER + /* glsl */ `
in vec2 vUv;
uniform vec2 uDir;    // step (texel * spread * axis)
uniform sampler2D uSrc;
out vec4 outColor;
const float W[7] = float[7](0.199, 0.176, 0.121, 0.065, 0.0275, 0.009, 0.0022);
void main() {
  vec4 acc = texture(uSrc, vUv) * W[0];
  for (int i = 1; i < 7; i++) {
    vec2 o = uDir * float(i);
    acc += texture(uSrc, clamp(vUv + o, vec2(0.0), vec2(1.0))) * W[i];
    acc += texture(uSrc, clamp(vUv - o, vec2(0.0), vec2(1.0))) * W[i];
  }
  outColor = acc;
}
`;

/** Additive composite fragment — the GLSL port of COMPOSITE_WGSL. */
export const buildGlowCompositeFragGLSL = (): string => GLSL_FRAG_HEADER + /* glsl */ `
in vec2 vUv;
uniform float uStrength;
uniform sampler2D uSrc;
out vec4 outColor;
void main() {
  vec4 g = texture(uSrc, vUv);
  outColor = vec4(g.rgb * uStrength, 0.0);   // additive: pure light
}
`;

interface GlowTarget { fbo: WebGLFramebuffer; tex: WebGLTexture }

export class GlGlowPass {
  private data: Float32Array = new Float32Array(256 * FLOATS);
  private count = 0;
  private capacity = 256;
  private maxSize = 0;
  private extraActive = false;
  private view = new Float32Array(4);

  private gl!: WebGL2RenderingContext;
  private stampProgram: WebGLProgram | null = null;
  private blurProgram: WebGLProgram | null = null;
  private compProgram: WebGLProgram | null = null;
  private uViewLoc: WebGLUniformLocation | null = null;
  private uDirLoc: WebGLUniformLocation | null = null;
  private uStrengthLoc: WebGLUniformLocation | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private instances!: InstanceBuffer;
  private targets: [GlowTarget, GlowTarget] | null = null;
  private targetW = 0;
  private targetH = 0;
  private atlasTexture: WebGLTexture | null = null;

  constructor(gl: WebGL2RenderingContext) {
    this.rebuild(gl);
  }

  get active(): boolean {
    return this.count > 0 || this.extraActive;
  }

  /** @internal Another system (the vector layer) wants the blur this frame
   * even if no sprite stamps: mark active and feed its glow size into the
   * blur-spread measure. */
  wake(size: number): void {
    this.extraActive = true;
    this.maxSize = Math.max(this.maxSize, size);
  }

  /** @internal Start a frame with the world view rect. */
  begin(x: number, y: number, w: number, h: number): void {
    this.count = 0;
    this.maxSize = 0;
    this.extraActive = false;
    this.view[0] = x; this.view[1] = y; this.view[2] = w; this.view[3] = h;
  }

  /** @internal Queue one glowing sprite's tinted silhouette (world coords) —
   *  identical packing to GlowPass.stamp. */
  stamp(
    x: number, y: number, w: number, h: number, f: Frame,
    rot: number, flipX: boolean,
    r: number, g: number, b: number, a: number, size: number,
  ): void {
    if (this.count === this.capacity) {
      this.capacity *= 2;
      const next = new Float32Array(this.capacity * FLOATS);
      next.set(this.data);
      this.data = next;
    }
    const o = this.count * FLOATS;
    const d = this.data;
    d[o] = x; d[o + 1] = y; d[o + 2] = w; d[o + 3] = h;
    d[o + 4] = rot; d[o + 5] = flipX ? 1 : 0; d[o + 6] = 0; d[o + 7] = 0;
    d[o + 8] = r; d[o + 9] = g; d[o + 10] = b; d[o + 11] = a;
    d[o + 12] = f.u0; d[o + 13] = f.v0; d[o + 14] = f.u1; d[o + 15] = f.v1;
    this.count++;
    this.maxSize = Math.max(this.maxSize, size);
  }

  private makeTarget(w: number, h: number): GlowTarget {
    const gl = this.gl;
    const tex = gl.createTexture()!;
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    const fbo = gl.createFramebuffer()!;
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
    return { fbo, tex };
  }

  /** @internal Render silhouette + blur chain (before the scene target is
   * bound). `extra` draws additional stamps into the same half-res pass (the
   * vector layer's soft line cores — it runs with our stamp FBO bound and the
   * viewport set); one blur serves every glowing thing. Restores the
   * framebuffer binding to null + full viewport before returning. */
  render(canvasW: number, canvasH: number, extra?: () => void): void {
    const gl = this.gl;
    const spriteStamps = this.count > 0 && !!this.atlasTexture && !!this.stampProgram;
    if (!spriteStamps && !this.extraActive) return;
    const w = Math.max(1, canvasW >> 1), h = Math.max(1, canvasH >> 1);
    if (!this.targets || this.targetW !== w || this.targetH !== h) {
      if (this.targets) {
        for (const t of this.targets) { gl.deleteFramebuffer(t.fbo); gl.deleteTexture(t.tex); }
      }
      this.targets = [this.makeTarget(w, h), this.makeTarget(w, h)];
      this.targetW = w;
      this.targetH = h;
    }
    const [A, B] = this.targets;

    // 1. stamp silhouettes into A (additive — overlapping glows sum)
    gl.bindFramebuffer(gl.FRAMEBUFFER, A.fbo);
    gl.viewport(0, 0, w, h);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.disable(gl.DEPTH_TEST);        // no depth attachment on this target
    gl.depthMask(false);
    if (!this.vao) this.vao = gl.createVertexArray();
    if (spriteStamps) {
      gl.useProgram(this.stampProgram);
      gl.uniform4fv(this.uViewLoc, this.view);
      gl.bindVertexArray(this.vao);
      this.instances.upload(this.data, this.count * FLOATS);
      instanceVec4Attribs(gl, 0, 4);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, this.atlasTexture);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE);
      gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, this.count);
      gl.bindVertexArray(null);
    }
    extra?.();                        // vector glow cores (they MAX-blend)
    gl.blendEquation(gl.FUNC_ADD);    // undo any MAX the extra stamps set

    // 2. separable blur, two iterations; spread follows the largest glow size
    if (this.blurProgram) {
      const spread = Math.min(3, Math.max(0.6, this.maxSize / 10));
      gl.useProgram(this.blurProgram);
      gl.disable(gl.BLEND);           // straight overwrite (fullscreen triangle)
      gl.bindVertexArray(this.vao);
      gl.activeTexture(gl.TEXTURE0);
      for (let i = 0; i < 2; i++) {
        this.blurTo(A, B, spread / w, 0);
        this.blurTo(B, A, 0, spread / h);
      }
      gl.bindVertexArray(null);
    }

    // Be tidy: hand the default framebuffer + full viewport back.
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, canvasW, canvasH);
  }

  private blurTo(from: GlowTarget, to: GlowTarget, dx: number, dy: number): void {
    const gl = this.gl;
    gl.bindFramebuffer(gl.FRAMEBUFFER, to.fbo);
    gl.viewport(0, 0, this.targetW, this.targetH);
    gl.uniform2f(this.uDirLoc, dx, dy);
    gl.bindTexture(gl.TEXTURE_2D, from.tex);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }

  /** @internal Additively composite the blurred glow into whatever
   * framebuffer is CURRENT (the renderer binds its scene target first). */
  composite(_pass?: unknown): void {
    const gl = this.gl;
    if (!this.active || !this.targets || !this.compProgram) return;
    gl.useProgram(this.compProgram);
    gl.uniform1f(this.uStrengthLoc, 1.15);
    if (!this.vao) this.vao = gl.createVertexArray();
    gl.bindVertexArray(this.vao);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.targets[0].tex);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE);     // additive: pure light
    gl.disable(gl.DEPTH_TEST);        // ignores depth entirely (WGSL: 'always')
    gl.depthMask(false);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.bindVertexArray(null);
  }

  /** Point the stamp pass at the shared atlas (a WebGLTexture here). */
  setTexture(view: unknown): void {
    this.atlasTexture = view as WebGLTexture;
  }

  /** (Re)create every GL-side object — the context-loss recovery path. */
  rebuild(gl: WebGL2RenderingContext): void {
    this.gl = gl;
    this.stampProgram = compileProgram(gl, buildGlowStampVertGLSL(), buildGlowStampFragGLSL(), 'GlGlowPass stamp');
    this.blurProgram = compileProgram(gl, buildFullscreenVertGLSL(), buildGlowBlurFragGLSL(), 'GlGlowPass blur');
    this.compProgram = compileProgram(gl, buildFullscreenVertGLSL(), buildGlowCompositeFragGLSL(), 'GlGlowPass composite');
    this.uViewLoc = this.stampProgram ? gl.getUniformLocation(this.stampProgram, 'uView') : null;
    this.uDirLoc = this.blurProgram ? gl.getUniformLocation(this.blurProgram, 'uDir') : null;
    this.uStrengthLoc = this.compProgram ? gl.getUniformLocation(this.compProgram, 'uStrength') : null;
    this.instances = new InstanceBuffer(gl);
    this.vao = null;
    this.targets = null;
    this.targetW = 0;
    this.targetH = 0;
    this.atlasTexture = null;
  }
}
