// The WebGL2 backend front door. Owns the GlContext and the full set of 2D
// batch twins, uploads the shared atlas, and replays the Game frame's
// composition order against GL state — the GL equivalent of the WebGPU encoder
// tail in game.ts's run loop:
//
//   backdrops → 3D world → glow prepass → lights-under → cutout → blend → tri
//   → vector → grid → fx → add → lights-over → msdf → HUD → post → HUD-above-fx
//
// Game constructs its Draw surfaces over these twins (they share the WebGPU
// batchers' begin/push/flush surface), so scenes, verbs, particles and text
// layout run identically on both backends.

import { GlContext } from './context.js';
import { textureFromSource } from './shaders.js';
import { GlQuadBatch } from './quadbatch.js';
import { DrawOrder, SRC_QUADS, SRC_CUTOUT, SRC_ADD, SRC_TRI } from '../batch.js';
import { GlTriBatch } from './tribatch.js';
import { GlMsdfRenderer } from './msdf.js';
import { GlUiRenderer } from './ui.js';
import { GlFxBatch } from './fxbatch.js';
import { GlGridBatch } from './gridbatch.js';
import { GlVectorLayer } from './vector.js';
import { GlGlowPass } from './glowpass.js';
import { GlPostChain } from './post.js';
import { GlBackdropChain } from './backdrop.js';
import { GlLights2d } from './lights2d.js';

export interface GlRendererOptions {
  dprCap?: number;
  onError?: (msg: string) => void;
  /** Blocky pixel-art sampling for the sprite batches (see GameOptions.pixelArt). */
  pixelArt?: boolean;
}

/** The scene-FBO handles a depth-consuming world renders against. */
export interface GlSceneTarget {
  fbo: WebGLFramebuffer;
  depthTex: WebGLTexture;
  width: number;
  height: number;
}

/** The 3D surface the renderer needs — implemented by GlWorld3d (webgl3d/). */
export interface GlWorldLike {
  render(width: number, height: number, scene?: GlSceneTarget | null): void;
  setTexture(view: unknown): void;
  /** True when a depth-consuming feature (SSAO / rays / underwater / soft
   * water) is live — the renderer then routes the WHOLE scene through the
   * offscreen FBO so its depth is a sampleable texture. */
  readonly needsDepthTexture?: boolean;
}

export interface GlFrameOptions {
  width: number;
  height: number;
  bg: readonly [number, number, number, number];
  time: number;
  world: GlWorldLike | null;
  hudAboveFx: boolean;
}

export class GlRenderer {
  readonly cutoutBatch: GlQuadBatch;
  readonly blendBatch: GlQuadBatch;
  readonly addBatch: GlQuadBatch;
  readonly hudBatch: GlQuadBatch;
  /** `d.text()` glyphs — world and screen. Flushed in the TEXT slot, over panels. */
  readonly textBatch: GlQuadBatch;
  readonly hudTextBatch: GlQuadBatch;
  readonly triBatch: GlTriBatch;
  readonly msdf: GlMsdfRenderer;
  /** The screen-space text pass (`game.hud`'s msdfText / unicodeText). */
  readonly msdfHud: GlMsdfRenderer;
  /** The UI panel passes — world space and screen space (see ui.ts). */
  readonly ui: GlUiRenderer;
  readonly uiHud: GlUiRenderer;
  readonly fxBatch: GlFxBatch;
  readonly gridBatch: GlGridBatch;
  readonly vector: GlVectorLayer;
  readonly glowPass: GlGlowPass;
  readonly postChain: GlPostChain;
  readonly backdrops: GlBackdropChain;
  /** Submission order per surface — quads and scene text interleaved. Owned by
   *  Game (it drives begin()); the renderer only reads them at draw time. */
  readonly sceneOrder = new DrawOrder();
  readonly hudOrder = new DrawOrder();
  private lights: GlLights2d | null = null;
  private atlasTexture: WebGLTexture | null = null;
  private world: GlWorldLike | null = null;

  /** The verbatim twin of Game.walkSurface — replay one surface's 2D content in
   *  the order the game drew it, one layer at a time. See there for why. */
  private walkSurface(
    order: DrawOrder,
    srcs: ReadonlyArray<{ drawRange(p: unknown, first: number, n: number): void } | null>,
  ): void {
    for (let n = 0; n <= order.maxLayer; n++) {
      for (const seg of order.segs) {
        if (seg.layer !== n) continue;
        srcs[seg.src]?.drawRange(undefined, seg.first, seg.n);
      }
    }
  }

  private constructor(readonly ctx: GlContext, opts: GlRendererOptions) {
    const gl = ctx.gl;
    const blocky = opts.pixelArt === true;
    this.cutoutBatch = new GlQuadBatch(gl, { cutout: true, blocky });
    this.blendBatch = new GlQuadBatch(gl, { cutout: false, blocky });
    this.addBatch = new GlQuadBatch(gl, { cutout: false, blend: 'add', blocky });
    this.hudBatch = new GlQuadBatch(gl, { cutout: false, depthTest: false, capacity: 4096, blocky });
    // Bitmap text rides in the TEXT slot (after the panel pass) and so never
    // depth-tests against the scene — the rule the MSDF pass already follows.
    this.textBatch = new GlQuadBatch(gl, { cutout: false, depthTest: false, blocky });
    this.hudTextBatch = new GlQuadBatch(gl, { cutout: false, depthTest: false, capacity: 4096, blocky });
    this.triBatch = new GlTriBatch(gl);
    this.msdf = new GlMsdfRenderer(gl);
    this.msdfHud = new GlMsdfRenderer(gl);
    this.ui = new GlUiRenderer(gl);
    this.uiHud = new GlUiRenderer(gl);
    this.fxBatch = new GlFxBatch(gl, { filter: blocky ? 'nearest' : 'linear' });
    this.gridBatch = new GlGridBatch(gl, { blocky });
    this.vector = new GlVectorLayer(gl);
    this.glowPass = new GlGlowPass(gl);
    this.postChain = new GlPostChain(gl);
    this.backdrops = new GlBackdropChain(gl);
    // Every 2D pass on the scene surface shares one submission-order log.
    this.blendBatch.joinOrder(this.sceneOrder, SRC_QUADS);
    this.cutoutBatch.joinOrder(this.sceneOrder, SRC_CUTOUT);
    this.addBatch.joinOrder(this.sceneOrder, SRC_ADD);
    this.triBatch.joinOrder(this.sceneOrder);
    this.gridBatch.joinOrder(this.sceneOrder);
    this.fxBatch.joinOrder(this.sceneOrder);
    // Context-restore recovery: rebuild every twin from CPU state. The Game's
    // own onRebuild callback re-uploads the atlas afterwards.
    ctx.onRebuild((newGl) => {
      this.cutoutBatch.rebuild(newGl);
      this.blendBatch.rebuild(newGl);
      this.addBatch.rebuild(newGl);
      this.hudBatch.rebuild(newGl);
      this.textBatch.rebuild(newGl);
      this.hudTextBatch.rebuild(newGl);
      this.triBatch.rebuild(newGl);
      this.msdf.rebuild(newGl);
      this.msdfHud.rebuild(newGl);
      this.ui.rebuild(newGl);
      this.uiHud.rebuild(newGl);
      this.fxBatch.rebuild(newGl);
      this.gridBatch.rebuild(newGl);
      this.vector.rebuild(newGl);
      this.glowPass.rebuild(newGl);
      this.postChain.rebuild(newGl);
      this.backdrops.rebuild(newGl);
      this.lights?.rebuild(newGl);
      this.atlasTexture = null;
    });
  }

  /** Acquire a WebGL2 context and stand the backend up. Null where absent. */
  static async init(canvas: HTMLCanvasElement, opts: GlRendererOptions = {}): Promise<GlRenderer | null> {
    const ctx = GlContext.init(canvas, { dprCap: opts.dprCap, onError: opts.onError });
    if (!ctx) return null;
    return new GlRenderer(ctx, opts);
  }

  get gl(): WebGL2RenderingContext { return this.ctx.gl; }

  fit(): boolean { return this.ctx.fit(); }
  get dead(): boolean { return this.ctx.dead; }
  markDirty(): void { this.ctx.markDirty(); }
  onRebuild(fn: () => void): () => void { return this.ctx.onRebuild(fn); }

  /** The 2D lights layer, created on first access (mirrors Game.lights2d). */
  createLights2d(): GlLights2d {
    this.lights ??= new GlLights2d(this.gl);
    return this.lights;
  }

  /** The GL 3D world, once game.world3d() has built one — lets the frame and
   *  atlas uploads reach it. */
  attachWorld(world: GlWorldLike | null): void {
    this.world = world;
    // A world attached AFTER the last atlas upload must still get the texture
    // (billboards/atlas-textured meshes sample white otherwise).
    if (world && this.atlasTexture) world.setTexture(this.atlasTexture);
  }

  /** Upload the packed atlas canvas and point every twin at it. */
  uploadAtlas(canvas: HTMLCanvasElement): void {
    const gl = this.gl;
    if (this.atlasTexture) gl.deleteTexture(this.atlasTexture);
    this.atlasTexture = textureFromSource(gl, canvas);
    this.cutoutBatch.setTexture(this.atlasTexture);
    this.blendBatch.setTexture(this.atlasTexture);
    this.addBatch.setTexture(this.atlasTexture);
    this.hudBatch.setTexture(this.atlasTexture);
    this.textBatch.setTexture(this.atlasTexture);
    this.hudTextBatch.setTexture(this.atlasTexture);
    this.fxBatch.setTexture(this.atlasTexture);
    this.gridBatch.setTexture(this.atlasTexture);
    this.glowPass.setTexture(this.atlasTexture);
    this.world?.setTexture(this.atlasTexture);
  }

  /** Upload an MSDF font atlas (no premultiply, linear — see msdf-font.ts). */
  msdfTexture(source: TexImageSource): WebGLTexture {
    return textureFromSource(this.gl, source, { premultiply: false, filter: 'linear' });
  }

  /** Upload a rasterized UnicodeText block (PREMULTIPLIED — the text pass blends premultiplied). */
  textTexture(source: TexImageSource): WebGLTexture {
    return textureFromSource(this.gl, source, { premultiply: true, filter: 'linear' });
  }

  /** Release a texture handed out by `textTexture` (a re-rasterized block). */
  deleteTexture(tex: WebGLTexture): void {
    this.gl.deleteTexture(tex);
  }

  /** Render one complete frame — the GL twin of the WebGPU encoder tail. */
  renderFrame(opts: GlFrameOptions): void {
    const gl = this.gl;
    const { width, height } = opts;
    const [r, g, b, a] = opts.bg;

    // Glow prepass runs offscreen BEFORE the scene target is bound.
    if (this.vector.glowSize > 0) this.glowPass.wake(this.vector.glowSize);
    this.vector.prepare();
    if (this.glowPass.active) {
      this.glowPass.render(width, height, () => this.vector.stampGlow(Math.max(1, width >> 1), Math.max(1, height >> 1)));
    }

    // With post effects active, the scene renders into the chain's offscreen
    // FBO and the chain lands on the canvas; the HUD is drawn after (unless
    // hudAboveFx=false pushes it through too) — game.ts's hudInScene logic.
    const post = this.postChain.active;
    const hudInScene = !post || !opts.hudAboveFx;

    // Scene target: the canvas, or the offscreen FBO — post effects need the
    // colour; a depth-consuming world (SSAO / rays / underwater) needs the
    // scene depth as a SAMPLEABLE texture, so it routes offscreen too and the
    // frame ends in a plain blit when no post chain runs.
    const offscreen = post || (opts.world?.needsDepthTexture ?? false);
    if (offscreen) this.postChain.sceneTarget(width, height);
    else gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, width, height);
    gl.disable(gl.SCISSOR_TEST);
    gl.disable(gl.CULL_FACE);
    gl.depthMask(true);
    gl.clearColor(r * a, g * a, b * a, a);   // premultiplied clear
    gl.clearDepth(1);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

    // Backdrops paint FIRST, behind everything (3D fog/meshes draw over).
    if (this.backdrops.active) this.backdrops.draw();

    // The 3D world renders with its own perspective depth, then the depth
    // buffer is cleared so the 2D layer stacks cleanly on top (the WebGPU path
    // uses two separate depth textures; one buffer + a clear is equivalent).
    if (opts.world) {
      opts.world.render(width, height, offscreen ? this.postChain.scene : null);
      gl.disable(gl.CULL_FACE);
      gl.depthMask(true);
      gl.clear(gl.DEPTH_BUFFER_BIT);
    }

    // The 2D scene stack, in the exact WebGPU composition order.
    this.glowPass.composite();               // blurred halos BEHIND the bodies
    this.lights?.draw(undefined, 'under');   // floor lights under the sprites
    // EVERY 2D pass, in the order the game drew it.
    this.walkSurface(this.sceneOrder, [
      this.blendBatch, this.msdf, this.ui, this.textBatch,
      this.cutoutBatch, this.addBatch, this.triBatch, this.gridBatch, this.fxBatch,
    ]);
    this.vector.draw(width, height);         // line art — retained, still fixed
    this.lights?.draw(undefined, 'over');    // overhead lights add over the scene
    if (hudInScene) {                          // HUD in-scene when no post
      this.walkSurface(this.hudOrder, [
        this.hudBatch, this.msdfHud, this.uiHud, this.hudTextBatch,
        this.hudBatch, this.hudBatch, null, null, null,
      ]);
    }

    if (post) {
      // Ping-pong the effect passes; the last one lands on the canvas.
      this.postChain.run(opts.time);
      // HUD above the effects: straight onto the canvas (the HUD batch draws
      // depth-free, so no fresh depth pass is needed on this backend).
      if (!hudInScene) {
        this.walkSurface(this.hudOrder, [
          this.hudBatch, this.msdfHud, this.uiHud, this.hudTextBatch,
          this.hudBatch, this.hudBatch, null, null, null,
        ]);
      }
    } else if (offscreen) {
      // Depth-seam frames (SSAO/rays/underwater, no post): plain blit home.
      this.postChain.blitToCanvas();
    }
  }

  destroy(): void {
    this.ctx.destroy();
  }
}
